func firstErr(n *sitter.Node, src []byte) string {
	if n.IsError() || n.IsMissing() {
		return fmt.Sprintf("line %d: %s", n.StartPoint().Row+1, strings.TrimSpace(strings.Split(string(src), "\n")[n.StartPoint().Row]))
	}
	for i := 0; i < int(n.ChildCount()); i++ {
		if s := firstErr(n.Child(i), src); s != "" {
			return s
		}
	}
	return ""
}

func TestZZMaskProbe(t *testing.T) {
	root := "/Users/rod/build/shunter"
	out, _ := exec.Command("git", "-C", root, "ls-files", "*.swift").Output()
	p := sitter.NewParser()
	p.SetLanguage(swift.GetLanguage())
