	for _, f := range strings.Fields(string(out)) {
		b, _ := os.ReadFile(root + "/" + f)
		rt, _ := p.ParseCtx(context.Background(), nil, b)
		masked := []byte(maskSwiftUnsupportedSyntax(string(b)))
